// ============================================
// Adjacency List Builder
// ============================================

const data = $input.first().json;
const students = data.students || [];
const courses = data.courses || [];

// Initialize empty adjacency list for every course
const adjacency = {};
courses.forEach(course => {
  adjacency[course.course_id] = new Set();
});

// Build conflicts from student enrolments
// If two courses share a student → they conflict
students.forEach(student => {
  const enrolled = student.courses || [];

  for (let i = 0; i < enrolled.length; i++) {
    for (let j = i + 1; j < enrolled.length; j++) {
      const c1 = enrolled[i];
      const c2 = enrolled[j];

      if (adjacency[c1] && adjacency[c2]) {
        adjacency[c1].add(c2);
        adjacency[c2].add(c1);
      }
    }
  }
});

// Convert Sets to sorted arrays (easier to read)
const adjacencyList = {};
Object.keys(adjacency).forEach(courseId => {
  adjacencyList[courseId] = Array.from(adjacency[courseId]).sort();
});

// Return the result + original data
return [{
  json: {
    ...data,
    adjacency_list: adjacencyList,
    adjacency_built: true
  }
}];

// ============================================
// DSATUR Scheduler (Time Slot Assignment)
// ============================================

const data = $input.first().json;
const adjacency = data.adjacency_list || {};
const timeSlots = data.time_slots || [];
const courses = Object.keys(adjacency);

// Map colour numbers to actual time slot IDs
const colourToSlot = {};
timeSlots.forEach((slot, index) => {
  colourToSlot[index + 1] = slot.slot_id;
});

// DSATUR state
const saturation = {};      // how many different colours are already used by neighbours
const degree = {};          // number of neighbours
const colour = {};          // assigned colour (0 = uncoloured)
const uncoloured = new Set(courses);

courses.forEach(c => {
  saturation[c] = 0;
  degree[c] = (adjacency[c] || []).length;
  colour[c] = 0;
});

// Helper: get the saturation degree of a course
function getSaturation(course) {
  const usedColours = new Set();
  (adjacency[course] || []).forEach(neighbour => {
    if (colour[neighbour] !== 0) {
      usedColours.add(colour[neighbour]);
    }
  });
  return usedColours.size;
}

// Main DSATUR loop
while (uncoloured.size > 0) {
  // Pick the uncoloured course with highest saturation
  // (break ties with highest degree)
  let selected = null;
  let maxSat = -1;
  let maxDeg = -1;

  for (const c of uncoloured) {
    const sat = getSaturation(c);
    const deg = degree[c];

    if (sat > maxSat || (sat === maxSat && deg > maxDeg)) {
      maxSat = sat;
      maxDeg = deg;
      selected = c;
    }
  }

  // Find the smallest colour not used by any neighbour
  const forbidden = new Set();
  (adjacency[selected] || []).forEach(n => {
    if (colour[n] !== 0) forbidden.add(colour[n]);
  });

  let chosenColour = 1;
  while (forbidden.has(chosenColour)) {
    chosenColour++;
  }

  // Assign the colour
  colour[selected] = chosenColour;
  uncoloured.delete(selected);
}

// Build the result: course → time slot
const timeAssignments = {};
const placed = [];
const unplaced = [];

courses.forEach(courseId => {
  const colourNum = colour[courseId];
  const slotId = colourToSlot[colourNum];

  if (slotId) {
    timeAssignments[courseId] = slotId;
    placed.push({
      course_id: courseId,
      timeslot: slotId
      // room will be assigned in the next step
    });
  } else {
    unplaced.push({
      course_id: courseId,
      reason_code: "NO_AVAILABLE_SLOT",
      detail: "Not enough time slots to avoid conflicts"
    });
  }
});

return [{
  json: {
    ...data,
    time_assignments: timeAssignments,
    placed: placed,
    unplaced: unplaced,
    violations_count: unplaced.length,
    dsatur_completed: true
  }
}];

// ============================================
// Room Assigner
// ============================================

const data = $input.first().json;
const placed = data.placed || [];
const rooms = data.rooms || [];
const courses = data.courses || [];
const timeSlots = data.time_slots || [];

// Quick lookup maps
const courseMap = {};
courses.forEach(c => courseMap[c.course_id] = c);

const roomUsage = {}; // track which rooms are used in which time slot
timeSlots.forEach(slot => {
  roomUsage[slot.slot_id] = new Set();
});

const finalPlaced = [];
const unplaced = [...(data.unplaced || [])];

placed.forEach(item => {
  const course = courseMap[item.course_id];
  if (!course) {
    unplaced.push({
      course_id: item.course_id,
      reason_code: "COURSE_NOT_FOUND",
      detail: "Course data missing"
    });
    return;
  }

  const neededCapacity = course.expected_students;
  const neededEquipment = course.required_equipment || [];
  const slotId = item.timeslot;

  // Find a suitable free room
  let assignedRoom = null;

  for (const room of rooms) {
    // Check if room is already used in this time slot
    if (roomUsage[slotId] && roomUsage[slotId].has(room.room_id)) continue;

    // Check capacity
    if (room.capacity < neededCapacity) continue;

    // Check equipment
    const hasAllEquipment = neededEquipment.every(eq => 
      (room.equipment || []).includes(eq)
    );
    if (!hasAllEquipment) continue;

    // Room is suitable
    assignedRoom = room;
    break;
  }

  if (assignedRoom) {
    roomUsage[slotId].add(assignedRoom.room_id);
    finalPlaced.push({
      course_id: item.course_id,
      room_id: assignedRoom.room_id,
      timeslot: item.timeslot,
      course_name: course.course_name,
      room_name: assignedRoom.room_name
    });
  } else {
    unplaced.push({
      course_id: item.course_id,
      reason_code: "NO_SUITABLE_ROOM",
      detail: `No free room with capacity ≥ ${neededCapacity} and required equipment`
    });
  }
});

return [{
  json: {
    ...data,
    placed: finalPlaced,
    unplaced: unplaced,
    violations_count: unplaced.length,
    rooms_assigned: true
  }
}];

